import functools


class AccesRefuse(Exception):
    pass


def exiger_role(role):
    def decorateur(fonction):
        @functools.wraps(fonction)
        def enveloppe(utilisateur, *args, **kwargs):
            if role not in utilisateur["roles"]:
                raise AccesRefuse(f"{utilisateur['nom']} n'a pas le rôle {role}")
            return fonction(utilisateur, *args, **kwargs)

        return enveloppe

    return decorateur


@exiger_role("conseiller")
