@dataclass
class Compte:
    iban: str
    titulaire: str
    solde: Decimal


class DepotComptesEnMemoire:
    def __init__(self) -> None:
        self._comptes: dict[str, Compte] = {}

    def enregistrer(self, compte: Compte) -> None:
        self._comptes[compte.iban] = compte

    def lister_par_titulaire(self, titulaire: str) -> list[Compte]:
        return [c for c in self._comptes.values() if c.titulaire == titulaire]


def solde_total(depot: DepotComptesEnMemoire, titulaire: str) -> Decimal:
    total = Decimal("0.00")
    for compte in depot.lister_par_titulaire(titulaire):
        total += compte.solde
    return total


