import copy
from decimal import Decimal


class UniteDeTravail:
    def __init__(self, base: dict[str, Decimal]) -> None:
        self._base = base

    def __enter__(self) -> "UniteDeTravail":
        # On travaille sur une copie : la base n'est pas touchée
        self.soldes = copy.deepcopy(self._base)
        return self

    def __exit__(self, type_erreur, erreur, trace) -> bool:
        if type_erreur is None:
            self._base.update(self.soldes)  # validation
            print("Validé")
        else:
            print(f"Annulé ({type_erreur.__name__})")  # la copie est jetée
        return False  # l'exception continue sa route


base = {"A": Decimal("100.00"), "B": Decimal("20.00")}


def virer(source: str, cible: str, montant: Decimal) -> None:
    with UniteDeTravail(base) as uow:
        uow.soldes[source] -= montant
        uow.soldes[cible] += montant


