class Horloge:
    def __init__(self) -> None:
        self.secondes = 0.0

    def maintenant(self) -> float:
        return self.secondes

    def avancer(self, secondes: float) -> None:
        self.secondes += secondes


class SeauAJetons:
    def __init__(self, horloge: Horloge, capacite: int, jetons_par_seconde: float) -> None:
        self.horloge = horloge
        self.capacite = capacite
        self.debit = jetons_par_seconde
        self.jetons = float(capacite)
        self.mise_a_jour = horloge.maintenant()

    def autoriser(self) -> bool:
        maintenant = self.horloge.maintenant()
        ecoule = maintenant - self.mise_a_jour
        self.jetons = min(self.capacite, self.jetons + ecoule * self.debit)
        self.mise_a_jour = maintenant
        if self.jetons >= 1:
            self.jetons -= 1
            return True
        return False


horloge = Horloge()
seaux: dict[str, SeauAJetons] = {}


def requete(client: str) -> int:
    """Renvoie le code HTTP de la réponse."""
    if client not in seaux:
        seaux[client] = SeauAJetons(horloge, capacite=3, jetons_par_seconde=1)
    return 200 if seaux[client].autoriser() else 429


