class ServicePaiement:
    def __init__(self) -> None:
        self.solde = Decimal("500.00")
        self.paiements = 0
        # clé -> (empreinte de la demande, réponse renvoyée)
        self._reponses: dict[str, tuple[str, dict[str, str]]] = {}

    def payer(self, cle: str, demande: dict[str, str]) -> dict[str, str]:
        empreinte = json.dumps(demande, sort_keys=True)
        if cle in self._reponses:
            empreinte_connue, reponse = self._reponses[cle]
            if empreinte != empreinte_connue:
