from dataclasses import dataclass
from decimal import Decimal


@dataclass(frozen=True)
class Evenement:
    nature: str  # "depot" ou "retrait"
    montant: Decimal


class Compte:
    def __init__(self) -> None:
        self.evenements: list[Evenement] = []

    def deposer(self, montant: Decimal) -> None:
        self.evenements.append(Evenement("depot", montant))

    def retirer(self, montant: Decimal) -> None:
        self.evenements.append(Evenement("retrait", montant))

    def soldes_successifs(self) -> list[Decimal]:
        soldes: list[Decimal] = []
        total = Decimal("0.00")
        for e in self.evenements:
            total += e.montant if e.nature == "depot" else -e.montant
            soldes.append(total)
        return soldes


compte = Compte()
compte.deposer(Decimal("200.00"))
compte.retirer(Decimal("50.00"))
compte.deposer(Decimal("30.00"))
print([str(solde) for solde in compte.soldes_successifs()])

