class Horloge:
    def __init__(self) -> None:
        self.secondes = 0.0


class ErreurTemporaire(Exception):
    pass


class CircuitOuvert(Exception):
    pass


class Limiteur:
    def __init__(self, horloge, capacite, debit):
        self.horloge, self.capacite, self.debit = horloge, capacite, debit
        self.jetons, self.vu = float(capacite), 0.0

    def autoriser(self):
        ecoule = self.horloge.secondes - self.vu
        self.jetons = min(self.capacite, self.jetons + ecoule * self.debit)
        self.vu = self.horloge.secondes
        if self.jetons >= 1:
            self.jetons -= 1
            return True
        return False


class Disjoncteur:
    def __init__(self, seuil):
        self.seuil, self.echecs = seuil, 0

    def appeler(self, operation):
        if self.echecs >= self.seuil:
            raise CircuitOuvert()
        try:
            resultat = operation()
        except ErreurTemporaire:
            self.echecs += 1
            raise
        self.echecs = 0
        return resultat


def avec_reessais(operation, tentatives):
    for tentative in range(1, tentatives + 1):
        try:
            return operation()
        except ErreurTemporaire:
            if tentative == tentatives:
                raise


class BanqueExterne:
    def __init__(self):
        self.appels = 0

    def debiter(self, montant):
        self.appels += 1
        if self.appels == 1:
            raise ErreurTemporaire("délai dépassé")
        return f"TX-{self.appels}"


class ApiPaiement:
    def __init__(self, horloge, banque):
        self.horloge, self.banque = horloge, banque
        self.limiteurs = {}
        self.reponses = {}
        self.disjoncteur = Disjoncteur(seuil=3)

    def post_paiement(self, client, cle, montant):
        limiteur = self.limiteurs.setdefault(client, Limiteur(self.horloge, 3, 1))
        if not limiteur.autoriser():
            return 429, "Trop de requêtes"
        if cle in self.reponses:
            return self.reponses[cle]
        try:
            transaction = self.disjoncteur.appeler(
                lambda: avec_reessais(lambda: self.banque.debiter(montant), 3)
            )
        except CircuitOuvert:
            return 503, "Banque indisponible, réessayez plus tard"
        except ErreurTemporaire:
            return 502, "La banque n'a pas répondu"
        reponse = (201, f"Paiement {transaction} accepté")
        self.reponses[cle] = reponse
        return reponse


horloge = Horloge()
banque = BanqueExterne()
api = ApiPaiement(horloge, banque)

print(api.post_paiement("boutique", "cle-1", "49.90"))
print(api.post_paiement("boutique", "cle-1", "49.90"))
print("Appels à la banque :", banque.appels)
print(api.post_paiement("boutique", "cle-2", "15.00"))
print(api.post_paiement("boutique", "cle-3", "8.00"))

blocs.markdown:
Ce que tu observes :

- le premier paiement a connu une erreur passagère, **absorbée** par le réessai : le client n'a rien vu ;
- le renvoi de `cle-1` n'a **pas** rappelé la banque : deux appels au total, un seul débit ;
- le quatrième appel dépasse la rafale autorisée : `429`, avant même de regarder la clé.

Pour rester lisible, ce code est simplifié : pas de typage complet, pas d'attente entre les réessais, un disjoncteur sans réouverture. Les leçons précédentes en donnent les versions complètes.

