from decimal import Decimal


class Banque:
    def __init__(self) -> None:
        self.appels = 0

    def debiter(self, montant: Decimal) -> str:
        self.appels += 1
        return f"TX-{self.appels}"


class ApiPaiement:
    def __init__(self, banque: Banque) -> None:
        self.banque = banque
        self.reponses: dict[str, tuple[int, str]] = {}

    def post_paiement(self, cle: str, montant: str) -> tuple[int, str]:
        if Decimal(montant) <= 0:
            return (422, "Montant invalide")
        if cle in self.reponses:
            return self.reponses[cle]
        transaction = self.banque.debiter(Decimal(montant))
        reponse = (201, f"Paiement {transaction} accepté")
        self.reponses[cle] = reponse
        return reponse


banque = Banque()
api = ApiPaiement(banque)
print(api.post_paiement("cle-1", "-5.00"))
print("Appels à la banque :", banque.appels)
print(api.post_paiement("cle-1", "5.00"))

